from fractions import Fraction
from typing import Any

from pymatgen.core import Structure
from pymatgen.symmetry.analyzer import SpacegroupAnalyzer


def _to_rational_str(x: float, max_denominator: int = 12) -> str:
    """Convert a float to a simplified rational string with bounded denominator."""
    # Keep values inside [0, 1) for fractional coordinates.
    x = x % 1.0
    frac = Fraction(x).limit_denominator(max_denominator)
    if frac.denominator == 1:
        return str(frac.numerator)
    return f"{frac.numerator}/{frac.denominator}"


def analyze_wyckoff_position_multiplicities_and_coordinates(filepath: str) -> dict[str, dict] | dict[str, Any]:
    """Analyze a CIF file and return Wyckoff multiplicities and representative coordinates.

    Returns
    -------
    dict
        {
            "wyckoff_multiplicity_dict": {"a": 4, ...},
            "wyckoff_coordinates_dict": {"a": ["0", "1/2", "1/2"], ...}
        }
    """
    structure = Structure.from_file(filepath)
    sga = SpacegroupAnalyzer(structure, symprec=1e-3)
    symm = sga.get_symmetrized_structure()

    multiplicity_dict: dict[str, int] = {}
    coordinates_dict: dict[str, list[str]] = {}

    for wyckoff_symbol, eq_indices in zip(symm.wyckoff_symbols, symm.equivalent_indices):
        # pymatgen gives symbols like "4a" or "8c"; extract the letter part.
        label = "".join(ch for ch in wyckoff_symbol if ch.isalpha())
        if not label:
            continue
        if label in multiplicity_dict:
            continue

        multiplicity_dict[label] = len(eq_indices)
        first_site = symm[eq_indices[0]]
        coordinates_dict[label] = [_to_rational_str(c) for c in first_site.frac_coords]

    return {
        "wyckoff_multiplicity_dict": multiplicity_dict,
        "wyckoff_coordinates_dict": coordinates_dict,
    }


if __name__ == "__main__":
    import sys
    import json

    result = analyze_wyckoff_position_multiplicities_and_coordinates(sys.argv[1])
    print(json.dumps(result, indent=2, ensure_ascii=False))
